(function(root){
 let state={configured:false,user:null};
 async function request(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{'Accept':'application/json',...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)}),redirect:'error',cache:'no-store',signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Account request failed.');return data;}
 root.DuaAccount={get state(){return state},async load(){state=await request('/api/account/session');return state;},async signin(email,password){state=await request('/api/account/signin','POST',{email,password});return state;},async signup(email,password,displayName){state=await request('/api/account/signup','POST',{email,password,displayName});return state;},async profile(displayName){const data=await request('/api/account/profile','PATCH',{displayName});state.user=data.user;return data;},async logout(){const data=await request('/api/account/logout','POST',{});state.user=null;return data;},cloud:()=>request('/api/cloud'),upload:(revision,snapshot)=>request('/api/cloud','PUT',{expectedRevision:revision,snapshot}),clearCloud:revision=>request('/api/cloud','DELETE',{expectedRevision:revision})};
})(globalThis);
